    17→// listCheckpoints returns all checkpoints from the sessions branch.
    18→// Uses checkpoint.GitStore.ListCommitted() for reading from entire/sessions.
    19→func (s *ManualCommitStrategy) listCheckpoints() ([]CheckpointInfo, error) {
    20→	store, err := s.getCheckpointStore()
    21→	if err != nil {
    22→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
    23→	}
    24→
    25→	committed, err := store.ListCommitted(context.Background())
    26→	if err != nil {
    27→		return nil, fmt.Errorf("failed to list committed checkpoints: %w", err)
    28→	}
    29→
    30→	// Convert from checkpoint.CommittedInfo to strategy.CheckpointInfo
    31→	result := make([]CheckpointInfo, 0, len(committed))
    32→	for _, c := range committed {
    33→		result = append(result, CheckpointInfo{
    34→			CheckpointID:     c.CheckpointID,
    35→			SessionID:        c.SessionID,
    36→			CreatedAt:        c.CreatedAt,
    37→			CheckpointsCount: c.CheckpointsCount,
    38→			FilesTouched:     c.FilesTouched,
    39→			Agent:            c.Agent,
    40→			IsTask:           c.IsTask,
    41→			ToolUseID:        c.ToolUseID,
    42→			SessionCount:     c.SessionCount,
    43→			SessionIDs:       c.SessionIDs,
    44→		})
    45→	}
    46→
    47→	return result, nil
    48→}
