    50→// getCheckpointsForSession returns all checkpoints for a session ID.
    51→func (s *ManualCommitStrategy) getCheckpointsForSession(sessionID string) ([]CheckpointInfo, error) {
    52→	all, err := s.listCheckpoints()
    53→	if err != nil {
    54→		return nil, err
    55→	}
    56→
    57→	var result []CheckpointInfo
    58→	for _, cp := range all {
    59→		if cp.SessionID == sessionID || strings.HasPrefix(cp.SessionID, sessionID) {
    60→			result = append(result, cp)
    61→		}
    62→	}
    63→
    64→	if len(result) == 0 {
    65→		return nil, fmt.Errorf("no checkpoints for session: %s", sessionID)
    66→	}
    67→
    68→	return result, nil
    69→}
