    93→// CondenseSession condenses a session's shadow branch to permanent storage.
    94→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
    95→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
    96→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
    97→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID string, state *SessionState) (*CondenseResult, error) {
    98→	// Get shadow branch
    99→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
   100→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   101→	ref, err := repo.Reference(refName, true)
   102→	if err != nil {
   103→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   104→	}
   105→
   106→	// Extract session data, starting from where we left off last condensation
   107→	// Use tracked files from session state instead of collecting all files from tree
   108→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.CondensedTranscriptLines, state.FilesTouched)
   109→	if err != nil {
   110→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   111→	}
   112→
   113→	// Get checkpoint store
   114→	store, err := s.getCheckpointStore()
   115→	if err != nil {
   116→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   117→	}
   118→
   119→	// Get author info
   120→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   121→
   122→	// Write checkpoint metadata using the checkpoint store
   123→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   124→		CheckpointID:     checkpointID,
   125→		SessionID:        state.SessionID,
   126→		Strategy:         StrategyNameManualCommit,
   127→		Transcript:       sessionData.Transcript,
   128→		Prompts:          sessionData.Prompts,
   129→		Context:          sessionData.Context,
   130→		FilesTouched:     sessionData.FilesTouched,
   131→		CheckpointsCount: state.CheckpointCount,
   132→		EphemeralBranch:  shadowBranchName,
   133→		AuthorName:       authorName,
   134→		AuthorEmail:      authorEmail,
   135→		Agent:            state.AgentType,
   136→	}); err != nil {
   137→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   138→	}
   139→
   140→	return &CondenseResult{
   141→		CheckpointID:         checkpointID,
   142→		SessionID:            state.SessionID,
   143→		CheckpointsCount:     state.CheckpointCount,
   144→		FilesTouched:         sessionData.FilesTouched,
   145→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   146→	}, nil
   147→}
   148→
   149→// extractSessionData extracts session data from the shadow branch.
   150→// startLine specifies the first line to include (0 = all lines, for incremental condensation).
   151→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   152→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, startLine int, filesTouched []string) (*ExtractedSessionData, error) {
   153→	commit, err := repo.CommitObject(shadowRef)
   154→	if err != nil {
   155→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   156→	}
   157→
   158→	tree, err := commit.Tree()
   159→	if err != nil {
   160→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   161→	}
   162→
   163→	data := &ExtractedSessionData{}
   164→	// sessionID is already an "entire session ID" (with date prefix), so construct path directly
   165→	// Don't use paths.SessionMetadataDir which would add another date prefix
   166→	metadataDir := paths.EntireMetadataDir + "/" + sessionID
   167→
   168→	// Extract transcript
   169→	var fullTranscript string
   170→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   171→		if content, contentErr := file.Contents(); contentErr == nil {
   172→			fullTranscript = content
   173→		}
   174→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   175→		if content, contentErr := file.Contents(); contentErr == nil {
   176→			fullTranscript = content
   177→		}
   178→	}
   179→
   180→	// Split into lines and filter
   181→	if fullTranscript != "" {
   182→		allLines := strings.Split(fullTranscript, "\n")
   183→
   184→		// Trim trailing empty lines (from final \n in JSONL)
   185→		for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   186→			allLines = allLines[:len(allLines)-1]
   187→		}
   188→
   189→		data.FullTranscriptLines = len(allLines)
   190→
   191→		// Get only lines from startLine onwards for this condensation
   192→		if startLine < len(allLines) {
   193→			newLines := allLines[startLine:]
   194→			data.Transcript = []byte(strings.Join(newLines, "\n"))
   195→
   196→			// Extract prompts from the new portion only
   197→			data.Prompts = extractUserPromptsFromLines(newLines)
   198→
   199→			// Generate context from prompts
   200→			data.Context = generateContextFromPrompts(data.Prompts)
   201→		}
   202→	}
   203→
   204→	// Use tracked files from session state (not all files in tree)
   205→	data.FilesTouched = filesTouched
   206→
   207→	return data, nil
   208→}
   209→
   210→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
   211→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   212→func extractUserPromptsFromLines(lines []string) []string {
   213→	var prompts []string
   214→	for _, line := range lines {
   215→		line = strings.TrimSpace(line)
   216→		if line == "" {
   217→			continue
   218→		}
   219→
   220→		var entry map[string]interface{}
   221→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
   222→			continue
   223→		}
   224→
   225→		// Check for user message (supports both "human" and "user" types)
   226→		msgType, ok := entry["type"].(string)
   227→		if !ok || (msgType != "human" && msgType != "user") {
   228→			continue
   229→		}
   230→
   231→		// Extract message content
   232→		message, ok := entry["message"].(map[string]interface{})
   233→		if !ok {
   234→			continue
   235→		}
   236→
   237→		// Handle string content
   238→		if content, ok := message["content"].(string); ok && content != "" {
   239→			cleaned := textutil.StripIDEContextTags(content)
   240→			if cleaned != "" {
   241→				prompts = append(prompts, cleaned)
   242→			}
   243→			continue
   244→		}
   245→
   246→		// Handle array content (e.g., multiple text blocks from VSCode)
   247→		if arr, ok := message["content"].([]interface{}); ok {
   248→			var texts []string
   249→			for _, item := range arr {
   250→				if m, ok := item.(map[string]interface{}); ok {
   251→					if m["type"] == "text" {
   252→						if text, ok := m["text"].(string); ok {
   253→							texts = append(texts, text)
   254→						}
   255→					}
   256→				}
   257→			}
   258→			if len(texts) > 0 {
   259→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   260→				if cleaned != "" {
   261→					prompts = append(prompts, cleaned)
   262→				}
   263→			}
   264→		}
   265→	}
   266→	return prompts
   267→}
   268→
   269→// generateContextFromPrompts generates context.md content from a list of prompts.
   270→func generateContextFromPrompts(prompts []string) []byte {
   271→	if len(prompts) == 0 {
   272→		return nil
   273→	}
   274→
   275→	var buf strings.Builder
   276→	buf.WriteString("# Session Context\n\n")
   277→	buf.WriteString("## User Prompts\n\n")
   278→
   279→	for i, prompt := range prompts {
   280→		// Truncate very long prompts for readability
   281→		displayPrompt := prompt
   282→		if len(displayPrompt) > 500 {
   283→			displayPrompt = displayPrompt[:500] + "..."
   284→		}
   285→		buf.WriteString(fmt.Sprintf("### Prompt %d\n\n", i+1))
   286→		buf.WriteString(displayPrompt)
   287→		buf.WriteString("\n\n")
   288→	}
   289→
   290→	return []byte(buf.String())
   291→}
