    18→// PrePromptState stores the state captured before a user prompt
    19→type PrePromptState struct {
    20→	SessionID      string   `json:"session_id"`
    21→	Timestamp      string   `json:"timestamp"`
    22→	UntrackedFiles []string `json:"untracked_files"`
    23→}
    24→
    25→// CapturePrePromptState captures current untracked files before a prompt
    26→// and saves them to a state file.
    27→// Works correctly from any subdirectory within the repository.
    28→func CapturePrePromptState(sessionID string) error {
    29→	if sessionID == "" {
    30→		sessionID = unknownSessionID
    31→	}
    32→
    33→	// Get absolute path for tmp directory
    34→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
    35→	if err != nil {
    36→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
    37→	}
    38→
    39→	// Create tmp directory if it doesn't exist
    40→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
    41→		return fmt.Errorf("failed to create tmp directory: %w", err)
    42→	}
    43→
    44→	// Get list of untracked files (excluding .entire directory itself)
    45→	untrackedFiles, err := getUntrackedFilesForState()
    46→	if err != nil {
    47→		return fmt.Errorf("failed to get untracked files: %w", err)
    48→	}
    49→
    50→	// Create state file
    51→	stateFile := prePromptStateFile(sessionID)
    52→	state := PrePromptState{
    53→		SessionID:      sessionID,
    54→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
    55→		UntrackedFiles: untrackedFiles,
    56→	}
    57→
    58→	data, err := json.MarshalIndent(state, "", "  ")
    59→	if err != nil {
    60→		return fmt.Errorf("failed to marshal state: %w", err)
    61→	}
    62→
    63→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
    64→		return fmt.Errorf("failed to write state file: %w", err)
    65→	}
    66→
    67→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files\n", len(untrackedFiles))
    68→	return nil
    69→}
