    71→// LoadPrePromptState loads previously captured state.
    72→// Returns nil if no state file exists.
    73→func LoadPrePromptState(sessionID string) (*PrePromptState, error) {
    74→	stateFile := prePromptStateFile(sessionID)
    75→
    76→	if !fileExists(stateFile) {
    77→		return nil, nil
    78→	}
    79→
    80→	data, err := os.ReadFile(stateFile) //nolint:gosec // Reading from controlled git metadata path
    81→	if err != nil {
    82→		return nil, fmt.Errorf("failed to read state file: %w", err)
    83→	}
    84→
    85→	var state PrePromptState
    86→	if err := json.Unmarshal(data, &state); err != nil {
    87→		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
    88→	}
    89→
    90→	return &state, nil
    91→}
