   102→// ComputeNewFiles compares current untracked files with pre-prompt state
   103→// to find files that were created during the session.
   104→func ComputeNewFiles(preState *PrePromptState) ([]string, error) {
   105→	if preState == nil {
   106→		return nil, nil
   107→	}
   108→
   109→	currentUntracked, err := getUntrackedFilesForState()
   110→	if err != nil {
