   117→// ComputeDeletedFiles returns files that were deleted during the session
   118→// (tracked files that no longer exist).
   119→func ComputeDeletedFiles() ([]string, error) {
   120→	repo, err := openRepository()
   121→	if err != nil {
   122→		return nil, err
   123→	}
   124→
   125→	worktree, err := repo.Worktree()
   126→	if err != nil {
   127→		return nil, err
   128→	}
   129→
   130→	status, err := worktree.Status()
   131→	if err != nil {
   132→		return nil, err
   133→	}
   134→
   135→	var deletedFiles []string
   136→	for file, st := range status {
   137→		// Skip .entire directory
   138→		if paths.IsInfrastructurePath(file) {
   139→			continue
   140→		}
   141→
   142→		// Find deleted files that haven't been staged yet
   143→		if st.Worktree == git.Deleted && st.Staging != git.Deleted {
   144→			deletedFiles = append(deletedFiles, file)
   145→		}
   146→	}
   147→
   148→	return deletedFiles, nil
   149→}
