   151→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   152→// infrastructure paths and paths outside the repo.
   153→func FilterAndNormalizePaths(files []string, cwd string) []string {
   154→	var result []string
   155→	for _, file := range files {
   156→		relPath := paths.ToRelativePath(file, cwd)
   157→		if relPath == "" {
   158→			continue // outside repo
   159→		}
   160→		if paths.IsInfrastructurePath(relPath) {
   161→			continue // skip .entire directory
   162→		}
   163→		result = append(result, relPath)
   164→	}
   165→	return result
   166→}
