   168→// prePromptStateFile returns the absolute path to the pre-prompt state file for a session.
   169→// Works correctly from any subdirectory within the repository.
   170→func prePromptStateFile(sessionID string) string {
   171→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   172→	if err != nil {
   173→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   174→	}
   175→	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-prompt-%s.json", sessionID))
   176→}
