   178→// getUntrackedFilesForState returns a list of untracked files using go-git
   179→// Excludes .entire directory
   180→func getUntrackedFilesForState() ([]string, error) {
   181→	repo, err := openRepository()
   182→	if err != nil {
   183→		return nil, err
   184→	}
   185→
   186→	worktree, err := repo.Worktree()
   187→	if err != nil {
   188→		return nil, err
   189→	}
   190→
   191→	status, err := worktree.Status()
   192→	if err != nil {
   193→		return nil, err
   194→	}
   195→
   196→	var untrackedFiles []string
   197→	for file, st := range status {
   198→		if st.Worktree == git.Untracked {
   199→			// Exclude .entire directory
   200→			if !strings.HasPrefix(file, paths.EntireDir+"/") && file != paths.EntireDir {
   201→				untrackedFiles = append(untrackedFiles, file)
   202→			}
   203→		}
   204→	}
   205→
   206→	return untrackedFiles, nil
   207→}
