   330→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   331→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   332→// When multiple pre-task files exist (nested subagents), returns the most recently
   333→// modified one.
   334→// Works correctly from any subdirectory within the repository.
   335→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
   336→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   337→	if err != nil {
   338→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   339→	}
   340→	entries, err := os.ReadDir(tmpDirAbs)
   341→	if err != nil {
   342→		return "", false
   343→	}
   344→
   345→	var latestFile string
   346→	var latestTime time.Time
   347→
   348→	for _, entry := range entries {
   349→		if entry.IsDir() {
   350→			continue
   351→		}
   352→		name := entry.Name()
   353→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   354→			continue
   355→		}
   356→
   357→		// Check modification time for nested subagent handling
   358→		info, err := entry.Info()
   359→		if err != nil {
   360→			continue
   361→		}
   362→		if latestFile == "" || info.ModTime().After(latestTime) {
   363→			latestFile = name
   364→			latestTime = info.ModTime()
   365→		}
   366→	}
   367→
   368→	if latestFile == "" {
   369→		return "", false
   370→	}
   371→
   372→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   373→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   374→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   375→	return toolUseID, true
   376→}
