   378→// DetectChangedFiles detects files that have been modified, added, or deleted
   379→// since the last commit (or compared to the index for incremental checkpoints).
   380→// Returns three slices: modified files, new (untracked) files, and deleted files.
   381→// Excludes .entire/ directory from all results.
   382→func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
   383→	repo, err := openRepository()
   384→	if err != nil {
   385→		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
   386→	}
   387→
   388→	worktree, err := repo.Worktree()
   389→	if err != nil {
   390→		return nil, nil, nil, fmt.Errorf("failed to get worktree: %w", err)
   391→	}
   392→
   393→	status, err := worktree.Status()
   394→	if err != nil {
   395→		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
   396→	}
   397→
   398→	for file, st := range status {
   399→		// Skip .entire directory
   400→		if paths.IsInfrastructurePath(file) {
   401→			continue
   402→		}
   403→
   404→		// Handle different status codes
   405→		// Worktree status indicates changes not yet staged
   406→		// Staging status indicates changes staged for commit
   407→		switch {
   408→		case st.Worktree == git.Untracked:
   409→			// New untracked file
   410→			newFiles = append(newFiles, file)
   411→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
   412→			// Deleted file
   413→			deleted = append(deleted, file)
   414→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
   415→			st.Worktree == git.Added || st.Staging == git.Added:
   416→			// Modified or staged file
   417→			modified = append(modified, file)
   418→		}
   419→	}
   420→
   421→	return modified, newFiles, deleted, nil
   422→}
