   424→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   425→// It counts existing checkpoint files in the task metadata checkpoints directory.
   426→// Returns 1 if no checkpoints exist yet.
   427→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   428→	// ctx.SessionID is already an Entire session ID (date-prefixed), so use SessionMetadataDirFromEntireID
   429→	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   430→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   431→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   432→
   433→	entries, err := os.ReadDir(checkpointsDir)
   434→	if err != nil {
   435→		// Directory doesn't exist or can't be read - start at 1
   436→		return 1
   437→	}
   438→
   439→	// Count JSON files (checkpoints)
   440→	count := 0
   441→	for _, entry := range entries {
   442→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   443→			count++
   444→		}
   445→	}
   446→
   447→	return count + 1
   448→}
