   225→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
   226→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
   227→	if err != nil {
   228→		return false
   229→	}
   230→
   231→	var settings ClaudeSettings
   232→	if err := json.Unmarshal(data, &settings); err != nil {
   233→		return false
   234→	}
   235→
   236→	// Check for at least one of our hooks (new or old format)
   237→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
   238→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
   239→		// Backwards compatibility: check for old hook formats
   240→		hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
   241→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
   242→		hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
   243→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
   244→}
