   257→// Helper functions for hook management
   258→
   259→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
   260→	for _, matcher := range matchers {
   261→		for _, hook := range matcher.Hooks {
   262→			if hook.Command == command {
   263→				return true
   264→			}
   265→		}
   266→	}
   267→	return false
   268→}
   269→
   270→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
   271→	for _, matcher := range matchers {
   272→		if matcher.Matcher == matcherName {
   273→			for _, hook := range matcher.Hooks {
   274→				if hook.Command == command {
   275→					return true
   276→				}
   277→			}
   278→		}
   279→	}
   280→	return false
   281→}
   282→
   283→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
   284→	entry := ClaudeHookEntry{
   285→		Type:    "command",
   286→		Command: command,
   287→	}
   288→
   289→	// If no matcher name, add to a matcher with empty string
   290→	if matcherName == "" {
   291→		for i, matcher := range matchers {
   292→			if matcher.Matcher == "" {
   293→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
   294→				return matchers
   295→			}
   296→		}
   297→		return append(matchers, ClaudeHookMatcher{
   298→			Matcher: "",
   299→			Hooks:   []ClaudeHookEntry{entry},
   300→		})
   301→	}
   302→
   303→	// Find or create matcher with the given name
   304→	for i, matcher := range matchers {
   305→		if matcher.Matcher == matcherName {
   306→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
   307→			return matchers
   308→		}
   309→	}
   310→
   311→	return append(matchers, ClaudeHookMatcher{
   312→		Matcher: matcherName,
   313→		Hooks:   []ClaudeHookEntry{entry},
   314→	})
   315→}
