   317→// isEntireHook checks if a command is an Entire hook (old or new format)
   318→func isEntireHook(command string) bool {
   319→	for _, prefix := range entireHookPrefixes {
   320→		if strings.HasPrefix(command, prefix) {
   321→			return true
   322→		}
   323→	}
   324→	return false
   325→}
   326→
   327→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
   328→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
   329→	result := make([]ClaudeHookMatcher, 0, len(matchers))
   330→	for _, matcher := range matchers {
   331→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
   332→		for _, hook := range matcher.Hooks {
   333→			if !isEntireHook(hook.Command) {
   334→				filteredHooks = append(filteredHooks, hook)
   335→			}
   336→		}
   337→		// Only keep the matcher if it has hooks remaining
   338→		if len(filteredHooks) > 0 {
   339→			matcher.Hooks = filteredHooks
   340→			result = append(result, matcher)
   341→		}
   342→	}
   343→	return result
   344→}
   345→
   346→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
   347→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
   348→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
   349→	// Same logic as removeEntireHooks - both work on the same structure
   350→	return removeEntireHooks(matchers)
   351→}
