    24→// parseTranscript reads and parses a Claude Code transcript file.
    25→// Uses bufio.Reader to handle arbitrarily long lines.
    26→func parseTranscript(path string) ([]transcriptLine, error) {
    27→	file, err := os.Open(path) //nolint:gosec // Reading from controlled git metadata path
    28→	if err != nil {
    29→		return nil, err
    30→	}
    31→	defer func() { _ = file.Close() }()
    32→
    33→	var lines []transcriptLine
    34→	reader := bufio.NewReader(file)
    35→
    36→	for {
    37→		lineBytes, err := reader.ReadBytes('\n')
    38→		if err != nil && err != io.EOF {
    39→			return nil, fmt.Errorf("failed to read transcript: %w", err)
    40→		}
    41→
    42→		// Handle empty line or EOF without content
    43→		if len(lineBytes) == 0 {
    44→			if err == io.EOF {
    45→				break
    46→			}
    47→			continue
    48→		}
    49→
    50→		var line transcriptLine
    51→		if err := json.Unmarshal(lineBytes, &line); err == nil {
    52→			lines = append(lines, line)
    53→		}
    54→
    55→		if err == io.EOF {
    56→			break
    57→		}
    58→	}
    59→
    60→	return lines, nil
    61→}
    62→
    63→// parseTranscriptFromLine reads and parses a transcript file starting from a specific line.
    64→// Uses bufio.Reader to handle arbitrarily long lines.
    65→// Returns:
    66→//   - lines: parsed transcript lines from startLine onwards (malformed lines skipped)
    67→//   - totalLines: total number of lines in the file (including malformed ones)
    68→//   - error: any error encountered during reading
    69→//
    70→// The startLine parameter is 0-indexed (startLine=0 reads from the beginning).
    71→// This is useful for incremental parsing when you've already processed some lines.
    72→func parseTranscriptFromLine(path string, startLine int) ([]transcriptLine, int, error) {
    73→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
    74→	if err != nil {
    75→		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
    76→	}
    77→	defer func() { _ = file.Close() }()
    78→
    79→	var lines []transcriptLine
    80→	reader := bufio.NewReader(file)
    81→
    82→	totalLines := 0
    83→	for {
    84→		lineBytes, err := reader.ReadBytes('\n')
    85→		if err != nil && err != io.EOF {
    86→			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
    87→		}
    88→
    89→		// Handle empty line or EOF without content
    90→		if len(lineBytes) == 0 {
    91→			if err == io.EOF {
    92→				break
    93→			}
    94→			continue
    95→		}
    96→
    97→		// Count all lines for totalLines, but only parse after startLine
    98→		if totalLines >= startLine {
    99→			var line transcriptLine
   100→			if err := json.Unmarshal(lineBytes, &line); err == nil {
   101→				lines = append(lines, line)
   102→			}
   103→		}
   104→		totalLines++
   105→
   106→		if err == io.EOF {
   107→			break
   108→		}
   109→	}
   110→
   111→	return lines, totalLines, nil
   112→}
