   114→// parseTranscriptFromBytes parses transcript content from a byte slice.
   115→// Uses bufio.Reader to handle arbitrarily long lines.
   116→func parseTranscriptFromBytes(content []byte) ([]transcriptLine, error) {
   117→	var lines []transcriptLine
   118→	reader := bufio.NewReader(bytes.NewReader(content))
   119→
   120→	for {
   121→		lineBytes, err := reader.ReadBytes('\n')
   122→		if err != nil && err != io.EOF {
   123→			return nil, fmt.Errorf("failed to read transcript: %w", err)
   124→		}
   125→
   126→		// Handle empty line or EOF without content
   127→		if len(lineBytes) == 0 {
   128→			if err == io.EOF {
   129→				break
   130→			}
   131→			continue
   132→		}
   133→
   134→		var line transcriptLine
   135→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   136→			lines = append(lines, line)
   137→		}
   138→
   139→		if err == io.EOF {
   140→			break
   141→		}
   142→	}
   143→
   144→	return lines, nil
   145→}
