   532→	if err != nil {
   533→		return fmt.Errorf("failed to create file: %w", err)
   534→	}
   535→	defer func() { _ = file.Close() }()
   536→
   537→	for _, line := range transcript {
   538→		data, err := json.Marshal(line)
   539→		if err != nil {
   540→			return fmt.Errorf("failed to marshal line: %w", err)
